"""Make sure that a is a subset of b, where None entries of a are ignored."""
def dicts_are_essentially_equal(a: Any, b: Any) -> object {
    for (k, v) in a.items() {
        if (v is None) {
            continue;
        }
        if (b.get(k) != v) {
            return False;
        }
    }
    return True;
}

